[{"id":"9","event_name":"Empowering Through Learning | Building Skills for Tomorrow","event_details":"At JM International SPC, we\u2019re passionate about turning learning into lasting impact. Our recent training session brought together a group of driven professionals who were eager to grow and strengthen their confidence in an ever-changing world.\nThrough interactive workshops and real-world insights, participants discovered new ways to lead, innovate, and make a difference in their workplaces.\nEvery session is a step toward our mission: to unlock potential and build the skills that shape a stronger, more sustainable future.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_jmiinternational-learninganddevelopment-upskilling-activity-7384235899292819456-TFJf?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-10-10","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a8e04a1f4.jpeg","photo2":null,"photo3":null,"enabled":"1","created_at":"2025-11-04 12:48:56"},{"id":"8","event_name":"Be the Change Youth Session","event_details":"JM International SPC engaged 250\u2013300 vibrant youth at St. Peter & Paul Catholic Church, Ruwi in a powerful session themed \u201cBe the Change \u2014 Your Work, Your Faith, Your Future.\u201d Participants were inspired to take ownership of their personal and professional growth, and live their faith authentically in their studies and careers. We also discussed building a future grounded in purpose, as well as becoming active agents of hope and positive change in our communities.\nThrough this session, JM International SPC encouraged the youth to shape a meaningful and impactful future.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_youthempowerment-faithinaction-bethechange-activity-7385788333072801792-2shC?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-10-17","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a85aa8763.jpeg","photo2":"..\/Uploads\/6909a85aa88d3.jpeg","photo3":"..\/Uploads\/6909a85aa89b6.jpeg","enabled":"1","created_at":"2025-11-04 12:42:29"},{"id":"3","event_name":"The Power of Social Media in Career Building","event_details":"At the German University of Technology in Oman (GUtech), JM International SPC led a session on utilizing social media for career advancement. Participants explored strategies for building professional presence and using online platforms to strengthen employability. The session reinforced JM International\u2019s mission to empower future leaders by connecting talent with opportunity.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_careerdevelopment-socialmediastrategy-linkedintips-activity-7333492546326761472-GpEM?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-05-28","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a5c64443e.jpeg","photo2":"..\/Uploads\/6909a5c6445cf.jpeg","photo3":"..\/Uploads\/6909a5c6446b3.jpeg","enabled":"1","created_at":"2025-08-28 16:26:04"},{"id":"5","event_name":"Career Development Day","event_details":"As part of Career Development Day at the German University of Technology in Oman (GUtech), JM International SPC held a special group session focused on career readiness and professional growth.\nThe session explored practical strategies for navigating today\u2019s competitive job market including CV writing, interview preparation, personal branding, and effective networking.\nThis initiative reflected GUtech\u2019s and JM International SPC\u2019s shared commitment to empowering young professionals with real-world insights and tools for lasting career success.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_careerdevelopmentday-jobsearch-careerstrategy-activity-7333378181908926464-vmu3?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-05-28","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a56f8f31e.jpeg","photo2":null,"photo3":null,"enabled":"1","created_at":"2025-10-17 00:05:56"},{"id":"6","event_name":"Winning in the Job Market: Strategic Job Search Using Social Media & Essential Career Skills","event_details":"At the German University of Technology in Oman (GUtech), JM International SPC conducted an engaging workshop for recent graduates focused on navigating today\u2019s competitive job market. The session offered practical strategies on leveraging social media and strengthening employability skills.\nParticipants described the workshop as insightful, practical, and empowering. JM International SPC extends its appreciation to GUtech for the collaboration and warm reception.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_jobsearch-careerskills-socialmediaforcareers-activity-7323085975616741377-drKx?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-04-30","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a3d3a884f.jpeg","photo2":"..\/Uploads\/6909a3d3a8a21.jpeg","photo3":"..\/Uploads\/6909a3d3a8b3c.jpeg","enabled":"1","created_at":"2025-10-17 00:07:13"},{"id":"10","event_name":"RUWI CUP Season 3","event_details":"We were thrilled to team up with Friends of Ruwi for the RUWI CUP 2025!\nThe event kicked off on 28 November 2025 at Al Sahil Football Turf, Darsait, and celebrated teamwork, talent, and community spirit. These values lie at the heart of JM International SPC.\n\nAs a people-driven organization, we\u2019re proud to champion initiatives that inspire healthy competition and bring communities together.","event_url":"https:\/\/www.instagram.com\/p\/DQ1_0VeAtkU\/?utm_source=ig_web_copy_link","posted_on":"2025-11-10","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/69118492d97e3.jpeg","photo2":null,"photo3":null,"enabled":"1","created_at":"2025-11-10 11:52:10"},{"id":"7","event_name":"The Impact of Artificial Intelligence on the Medical Sector","event_details":"JM International SPC was honored with a Certificate of Appreciation from the Higher Institute of Health Specialties (HIHS) for conducting a session on \"The Impact of Artificial Intelligence on the Medical Sector\".\nThe session explored how AI is reshaping healthcare through advancements such as predictive diagnostics and personalized patient care, highlighting both opportunities and responsibilities in this evolving field.\nJM International SPC extends sincere appreciation to Dr. Manal Abdul Majeed Al Zadjali, Dean of HIHS, and Dr. German M. Verosil Jr., Chairperson of CPDC, for their recognition and partnership in preparing the healthcare workforce for the future of AI.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_aiinhealthcare-futureofwork-nursingeducation-activity-7353714474748379136-Lshl?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-07-23","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6909a677de4cf.jpeg","photo2":"..\/Uploads\/6909a677de637.jpeg","photo3":"..\/Uploads\/6909a677de721.jpeg","enabled":"1","created_at":"2025-11-04 12:38:39"},{"id":"13","event_name":"Holiday Gathering | AmCham Oman","event_details":"JM International SPC was pleased to be part of AmCham Oman\u2019s Holiday Gathering. The evening brought together members of Oman\u2019s diverse international business community for meaningful conversations, warm connections, and a festive atmosphere. It was a wonderful opportunity to celebrate the spirit of collaboration that continues to strengthen the business landscape in Oman. Our thanks to AmCham Oman for hosting a memorable and well-curated evening.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_amchamoman-networking-businesscommunity-activity-7407419580643430400-8nz6?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2025-12-22","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/694c93b508ea3.jpeg","photo2":"..\/Uploads\/694c93b5091b1.jpeg","photo3":null,"enabled":"1","created_at":"2025-12-22 12:40:06"},{"id":"14","event_name":"Workforce Management Best Practices Session","event_details":"JM International SPC recently conducted a collaborative session with Sadad International LLC, sharing practical workforce management and compliance frameworks aligned with Oman Labour Law. The discussion covered key areas including performance management, disciplinary procedures, project deployment, and supervisor responsibilities, with a strong focus on clarity, consistency, and fairness. We thank the Sadad team for their active participation and look forward to strengthening our ongoing partnership.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_jminternationalspc-sadadinternational-hrcompliance-activity-7417199686916214785-P5Sg?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2026-01-14","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6967b7d92600a.png","photo2":"..\/Uploads\/6967b7d9265cb.png","photo3":null,"enabled":"1","created_at":"2026-01-14 21:05:53"},{"id":"15","event_name":"Oman Internship Fair 2026","event_details":"JM International SPC was pleased to participate in the Oman Internship Fair hosted by The Diplomatic Club, bringing together students, institutions, and employers to explore early career opportunities.\n\nThe event provided a valuable platform to engage with talented students, discuss career pathways, and share insights into internships and future workforce readiness. It was encouraging to see strong interest, thoughtful conversations, and a shared commitment to developing the next generation of professionals in Oman.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_jminternationalspc-omaninternshipfair2026-activity-7421433407647350784-PVZ6?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2026-01-26","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6979cb4bf405c.png","photo2":"..\/Uploads\/6979cb4c03854.png","photo3":"..\/Uploads\/6979cb4c3fce7.png","enabled":"1","created_at":"2026-01-28 14:09:40"},{"id":"20","event_name":"Welcoming New Talent at Sadad: Employee Induction Program","event_details":"An engaging induction session conducted at Sadad International LLC, introducing new employees to their roles, responsibilities, and key company policies in line with Oman Labour Law. Focused on clarity, compliance, and a smooth start, the session set the foundation for a confident and informed workforce.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_jminternationalspc-employeeinduction-onboarding-ugcPost-7454116856417656832-biVp?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2026-04-26","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/69ef1d7e308e6.png","photo2":"..\/Uploads\/69ef1d7e30f6a.png","photo3":"..\/Uploads\/69ef1d7e31304.png","enabled":"1","created_at":"2026-04-27 13:55:34"},{"id":"18","event_name":"Driving Conversations at the OER Business Summit 2026","event_details":"JM International SPC attended the OER Business Summit 2026, where business leaders and industry experts came together to exchange perspectives on Oman\u2019s evolving economic landscape.\n\nFrom discussions around diversification and workforce development to practical insights on building resilient organizations, the conversations were both grounded and forward-looking. With strong participation from across sectors, the event reflected a shared commitment to shaping sustainable growth in line with Oman\u2019s long-term vision.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_oman-oer-businesssummit-ugcPost-7444668435151740928-ZsqE?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2026-03-31","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/69d60b1f00325.png","photo2":"..\/Uploads\/69d60b1f007e5.png","photo3":"..\/Uploads\/69d60b1f16837.png","enabled":"1","created_at":"2026-04-08 13:28:00"},{"id":"21","event_name":"Al Mar'a Summit and Awards 2026","event_details":"We are proud to share that JM International SPC has been recognised at the recent Al Mar'a Summit and Awards 2026.\n\nThis recognition reflects the journey we are on and the values we stand for. We are grateful to the organisers for creating a platform around the powerful theme \u201cLeadership of Women & the Future Economy: Leading Industrial Transformation and Sustainable Innovation.\u201d\n\nThe conversations at the conference reinforced the vital role Omani women continue to play in driving innovation, sustainability, and economic diversification in line with Oman Vision 2040. We were especially honoured to hear the insightful panel led by the distinguished speakers on how women can confidently approach and succeed in business.\n\nAt JM International SPC, our mission remains clear: Empowering People. Enabling Progress. We are committed to developing Omani talent, delivering impactful workforce solutions, and contributing to the nation\u2019s growth.\n\nOur sincere thanks to our supporters and well-wishers who continue to believe in our journey.\n\nTo every aspiring woman leader, your voice matters. Step forward and shape the future.","event_url":"https:\/\/www.linkedin.com\/posts\/jessy-mathew-55318b99_almaraawards2026-jminternationalspc-nationaltalentdevelopment-ugcPost-7462791326049132544-nBQQ?utm_source=share&utm_medium=member_desktop&rcm=ACoAADeJTPMBpaoDYoJJgGsNjJlt8I6XK--leRM","posted_on":"2026-05-20","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6a0ece1acb2d8.png","photo2":"..\/Uploads\/6a0ece1aec043.png","photo3":"..\/Uploads\/6a0ece1b308c5.png","enabled":"1","created_at":"2026-05-21 14:49:24"},{"id":"22","event_name":"Team Meeting at Rozna","event_details":"An evening at Rozna Restaurant, Seeb, where Omani heritage meets warm hospitality, felt like the right setting to pause and appreciate the people behind JM International SPC.\nIt was a moment to recognize the individuals who quietly push things forward, challenge ideas, and turn everyday work into something that actually matters.","event_url":"https:\/\/www.linkedin.com\/in\/jessy-mathew-55318b99","posted_on":"2026-06-17","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6a3cfffa3b129.png","photo2":"..\/Uploads\/6a3cfffa3b9cc.png","photo3":"..\/Uploads\/6a3cfffa70326.png","enabled":"1","created_at":"2026-06-25 10:15:36"},{"id":"23","event_name":"A Fond Farewell to Our HR Intern","event_details":"We are pleased to share the successful completion of Mr Dhanush K Krishna\u2019s HR Internship at JM International SPC. To mark the occasion, our team hosted a farewell lunch at Tanatan, Muscat, where we had the pleasure of presenting him with his Experience Certificate and a token of appreciation for his contributions and dedication during his time with us. We wish him continued success in his future academic and professional journey.","event_url":"https:\/\/www.linkedin.com\/in\/jessy-mathew-55318b99\/","posted_on":"2026-07-30","posted_by":"Jessy Mathew International SPC","photo1":"..\/Uploads\/6a6dfa9dea201.png","photo2":"..\/Uploads\/6a6dfa9e1bd5d.png","photo3":"..\/Uploads\/6a6dfa9e587d5.png","enabled":"1","created_at":"2026-08-01 19:24:38"}]